From 03141eaffd37d358c0fec02ce62401265b5ba7c1 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 15:18:31 +0100
Subject: [PATCH] libtaskmanager: ignore launchers on other activities when
 sorting

With launch-in-place sorting, a window was sorted into its launcher's slot
even when the app was only pinned on another activity, so it jumped to the
front. Now only launchers on the current activity are taken into account.

BUG: 386055
---
 libtaskmanager/tasksmodel.cpp | 22 +++++++++++++++++++---
 1 file changed, 19 insertions(+), 3 deletions(-)

diff --git a/libtaskmanager/tasksmodel.cpp b/libtaskmanager/tasksmodel.cpp
index fd6246a363..36a1244d0d 100644
--- a/libtaskmanager/tasksmodel.cpp
+++ b/libtaskmanager/tasksmodel.cpp
@@ -85,6 +85,7 @@ public:
     void forceResort();
     bool lessThan(const QModelIndex &left, const QModelIndex &right, bool sortOnlyLaunchers = false) const;
     std::optional<bool> lessThanByVirtualDesktop(const QModelIndex &left, const QModelIndex &right) const;
+    int launcherPositionOnActivity(const QUrl &url) const;

 private:
     TasksModel *const q;
@@ -728,6 +729,21 @@ std::optional<bool> TasksModel::Private::lessThanByVirtualDesktop(const QModelIn
     return std::nullopt;
 }

+int TasksModel::Private::launcherPositionOnActivity(const QUrl &url) const
+{
+    const int pos = q->launcherPosition(url);
+
+    if (pos != -1 && filterProxyModel->filterByActivity() && !q->activity().isEmpty()) {
+        const QStringList activities = launcherTasksModel->launcherActivities(url);
+
+        if (!activities.contains(NULL_UUID) && !activities.contains(q->activity())) {
+            return -1;
+        }
+    }
+
+    return pos;
+}
+
 bool TasksModel::Private::lessThan(const QModelIndex &left, const QModelIndex &right, bool sortOnlyLaunchers) const
 {
     // Launcher tasks go first.
@@ -742,8 +758,8 @@ bool TasksModel::Private::lessThan(const QModelIndex &left, const QModelIndex &r
             return (left.row() < right.row());
         }

-        const int leftPos = q->launcherPosition(left.data(AbstractTasksModel::LauncherUrlWithoutIcon).toUrl());
-        const int rightPos = q->launcherPosition(right.data(AbstractTasksModel::LauncherUrlWithoutIcon).toUrl());
+        const int leftPos = launcherPositionOnActivity(left.data(AbstractTasksModel::LauncherUrlWithoutIcon).toUrl());
+        const int rightPos = launcherPositionOnActivity(right.data(AbstractTasksModel::LauncherUrlWithoutIcon).toUrl());

         if (leftIsLauncher && !rightIsLauncher) {
             if (launchInPlace) {
@@ -1645,7 +1661,7 @@ bool TasksModel::move(int row, int newPos, const QModelIndex &parent)
             // When using launch-in-place sorting, launcher-backed window tasks act as launchers.
         } else if ((d->launchInPlace || !d->separateLaunchers) && idx.data(AbstractTasksModel::IsWindow).toBool()) {
             const QUrl &launcherUrl = idx.data(AbstractTasksModel::LauncherUrlWithoutIcon).toUrl();
-            const int launcherPos = launcherPosition(launcherUrl);
+            const int launcherPos = d->launcherPositionOnActivity(launcherUrl);

             if (launcherPos != -1) {
                 isLauncherMove = true;
